      "description": "뉴욕타임스 기사와 교육 콘텐츠",
      "officialDescription": "1. 전 세계적인 유력 언론사, 뉴욕타임스사에서 제공하는 온라인 교육 플랫폼\n2. 뉴욕타임스 기사를 이용하여 다양한 교수 및 학습, Case Studies, 대학강의 리소스로 활용\n3. 프리미엄 영어 컨텐츠 – 다수의 수상 경력과 고품질의 영어 컨텐츠 및 학습도구\n4. 국제관계, 경제, 환경과학 등 16개의 주제 분야로 구성, - 주제전문가에 의해 엄선된 기사와 시놉시스\n5. 실시간 업데이트 뉴스, Wellness 및 Smart Living 컨텐츠, 온라인 수업 등 여러 분야의 유용한 학생용 컨텐츠\n6. 뉴욕타임스 디지털 신문과 연계하여, 뉴욕타임스 전체 컨텐츠 이용 가능",
