      "officialDescription": "- 대출정책 : 5책 5일(1회 연장 가능)\n- PC와 스마트기기(\"알라딘 전자도서관\", \"교보문고 전자도서관\" APP 사용) 이용 가능\n* 스마트기기 이용방법\n 1. 반드시 사전에 도서관 홈페이지에서 전자책 사이트(왼쪽 아이콘) 접근 후 이용해주십시오.\n 2. 앱스토어 또는 플레이스토어에서 \"알라딘 전자도서관\", \"교보문고 전자도서관\" 어플리케이션을 검색하여 설치\n 3. 설치한 어플리케이션 실행 후, \"도서관 검색\" 메뉴에서 '제주대학교' 검색\n 4. 로그인 ID와 PW는 도서관 홈페이지 계정으로 로그인 해주십시오.\n\n계정 관련 최신 안내는 공식 페이지에서 확인하세요.",
