      "officialDescription": "- 베스트셀러와 신간도서를 언제 어디서나 무제한 읽을 수 있는 eBook\n- 이용권 발급방법\n 1. PC 또는 모바일에서 제주대학교 도서관 홈페이지 로그인\n 2. 자료검색>전자책>예스24 크레마클럽(왼쪽 아이콘) 클릭\n 3. 예스24 로그인 (최초 로그인 시 이용권 자동 발급)\n* 계정 없는 이용자는 회원 가입 필수 / 기존 이용자는 ID 사용\n- 이용방법\n- 크레마클럽 홈페이지>읽고 싶은 책 선택>바로가기 클릭\n- 바로 읽기 클릭하면 전용뷰어 자동 다운로드\n* 자동설치 안 되면 (모바일) 앱 다운로드 / (PC) 전용뷰어 다운로드\n- 이용문의 : 1544-3800(예스24 고객센터)",
